package com.portfolio.hireflow.integration.calendar.service;
import java.time.Instant;import org.slf4j.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.data.domain.PageRequest;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import com.portfolio.hireflow.integration.calendar.entity.*;import com.portfolio.hireflow.integration.calendar.repository.*;
@Service
public class CalendarSyncDispatchService{
 private static final Logger log=LoggerFactory.getLogger(CalendarSyncDispatchService.class);private final CalendarSyncJobRepository jobs;private final GoogleCalendarEventLinkRepository links;private final ObjectProvider<GoogleCalendarApiService> apis;
 public CalendarSyncDispatchService(CalendarSyncJobRepository jobs,GoogleCalendarEventLinkRepository links,ObjectProvider<GoogleCalendarApiService> apis){this.jobs=jobs;this.links=links;this.apis=apis;}
 @Scheduled(fixedDelayString="${app.google-calendar.dispatch-delay-ms:60000}") public void dispatch(){if(apis.getIfAvailable()==null)return;jobs.findDue(Instant.now(),PageRequest.of(0,20)).forEach(j->{try{sync(j.getId());}catch(Exception e){log.warn("Calendar sync job {} failed",j.getId(),e);}});}
 @Transactional(propagation=Propagation.REQUIRES_NEW) public void sync(Long id){CalendarSyncJob j=jobs.findById(id).orElse(null);if(j==null)return;try{GoogleCalendarApiService api=apis.getIfAvailable();if(api==null)return;var existing=links.findByInterviewIdAndUserId(j.getInterview().getId(),j.getUser().getId());if(j.getOperation()==CalendarSyncOperation.DELETE){if(existing.isPresent()){api.delete(j.getUser().getId(),existing.get().getGoogleEventId());links.delete(existing.get());}}else if(existing.isPresent()){api.update(j.getUser().getId(),existing.get().getGoogleEventId(),j.getInterview());existing.get().synced();}else{String eventId=api.create(j.getUser().getId(),j.getInterview());links.save(new GoogleCalendarEventLink(j.getInterview(),j.getUser(),eventId));}j.completed();}catch(Exception e){log.warn("Google Calendar sync failed",e);j.failed();}}
}
